--
-- Table structure for table `token_server`
--

DROP TABLE IF EXISTS `token_server`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `token_server` (
  `id_token_server` int NOT NULL AUTO_INCREMENT,
  `id_token` int DEFAULT NULL,
  `type` varchar(8) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Tipo de encripcion AES DES JASCRIPT',
  `server` varchar(8) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Servidor que esta utilizando WL12=weblogic 12c  WF19=wildfly 19, GF5 glassfish 5',
  `password` varchar(512) DEFAULT NULL COMMENT 'Clave que se ha guardado password',
  `user_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Fecha de insercion del registro',
  `user_app` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Programa usado para el cambio',
  PRIMARY KEY (`id_token_server`),
  KEY `token_server_index_IDX` (`type`),
  KEY `token_server_FK` (`id_token`),
  CONSTRAINT `token_servidor_FK` FOREIGN KEY (`id_token`) REFERENCES `token` (`id_token`)
) ENGINE=InnoDB AUTO_INCREMENT=4194 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `token_server`
--

LOCK TABLES `token_server` WRITE;
/*!40000 ALTER TABLE `token_server` DISABLE KEYS */;
/*!40000 ALTER TABLE `token_server` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `user`
--

DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `id_user` int NOT NULL AUTO_INCREMENT,
  `nick` varchar(128) DEFAULT NULL COMMENT 'Nick de Usuario',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Nombre de Usuario',
  `last_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Apellido de Usuario',
  `validator` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Campo de validacion para los registros',
  `income_counter` int DEFAULT NULL COMMENT 'Contador de intentos fallidos',
  `income_date` datetime DEFAULT NULL COMMENT 'Fecha y hora del intentos fallidos',
  `status` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Estado del listado A=Activo, I=Inactivo y X=Eliminado',
  `uuid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'UUID para indice unico de consulta',
  `user` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Usuario que realizo el cambio',
  `user_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Fecha de insercion del registro',
  `user_app` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Programa usado para el cambio',
  PRIMARY KEY (`id_user`),
  UNIQUE KEY `user_nick_IDX` (`nick`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=215 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

