--
-- Table structure for table `user_defined_code`
--

DROP TABLE IF EXISTS `user_defined_code`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_defined_code` (
  `id_user_defined_code` int NOT NULL AUTO_INCREMENT,
  `id_module` int NOT NULL,
  `group` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Grupo de listas',
  `code_text` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Codigo para los campos de: estado, tipo, grupo y/o categoría',
  `code_number` int NOT NULL COMMENT 'Codigo para los campos de: estado, tipo y/o categoría',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Nombre del campo',
  `description` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Descripción del campo para presentación',
  `order` int NOT NULL COMMENT 'Orden de presentacion',
  `status` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Estado del listado A=Activo, I=Inactivo y X=Eliminado',
  `user` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Usuario que realizo el cambio',
  `user_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Fecha de insercion del registro',
  `user_app` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Programa usado para el cambio',
  PRIMARY KEY (`id_user_defined_code`),
  KEY `user_defined_code_id_module_IDX` (`id_module`,`group`) USING BTREE,
  KEY `user_defined_code_code_text_IDX` (`code_text`) USING BTREE,
  KEY `user_defined_code_code_number_IDX` (`code_number`) USING BTREE,
  CONSTRAINT `codigo_definido_usuario_FK` FOREIGN KEY (`id_module`) REFERENCES `module` (`id_module`)
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

